import java.io.*;
import java.util.*;

public class Variant5 {
  static PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

  int R, C;
  long[][] binomial = new long[61][61];
  int[] numA = new int[61], numB = new int[61];
  long minDifference = Long.MAX_VALUE;
  String chars;
  Map<String, Long> cache = new HashMap<>();

  public static void main(String[] args) {
    Variant5 program = new Variant5();
    program.run();
    pw.flush();
  }

  static int nextIntValue() {
    int value = 0;
    boolean negative = false;
    try {
      boolean inNumber = false;
      for (int ch = 0; (ch = System.in.read()) != -1; ) {
        if (ch == '-') {
          inNumber = true;
          negative = true;
          continue;
        } else if (ch >= '0' && ch <= '9') {
          inNumber = true;
          value = value * 10 + ch - '0';
        } else if (inNumber) break;
      }
    } catch (IOException ignore) {}
    return negative ? -value : value;
  }

  static long nextLongValue() {
    long value = 0;
    boolean negative = false;
    try {
      boolean inNumber = false;
      for (int ch = 0; (ch = System.in.read()) != -1; ) {
        if (ch == '-') {
          inNumber = true;
          negative = true;
          continue;
        } else if (ch >= '0' && ch <= '9') {
          inNumber = true;
          value = value * 10 + ch - '0';
        } else if (inNumber) break;
      }
    } catch (IOException ignore) {}
    return negative ? -value : value;
  }

  static String nextStringValue() {
    StringBuilder buffer = new StringBuilder();
    try {
      boolean inToken = false;
      for (int ch = 0; (ch = System.in.read()) != -1; ) {
        if (Character.isLetterOrDigit(ch) || ch == '?') {
          inToken = true;
          buffer.append((char) ch);
        } else if (inToken) break;
      }
    } catch (IOException ignore) {}
    return buffer.toString();
  }

  static int nextCharArray(char[] array, int offset) {
    int length = 0;
    try {
      boolean inToken = false;
      for (int ch = 0; (ch = System.in.read()) != -1; ) {
        if (Character.isLetterOrDigit(ch)) {
          inToken = true;
          array[offset + length++] = (char) ch;
        } else if (inToken) break;
      }
    } catch (IOException ignore) {}
    return length;
  }

  void traverse(long leftSum, long rightSum, int index1, int index2) {
    long diff = Math.abs(leftSum - rightSum);
    if (minDifference <= 1 || diff - binomial[index1][R] * binomial[index2][R] >= minDifference) return;
    if (index1 == R - 1 && index2 == R - 1) {
      if (diff < minDifference) minDifference = diff;
      return;
    }
    if (index1 >= R) {
      long delta = binomial[index1][R] - binomial[index1 - 1][R];
      long multiplier = binomial[index2][R];
      traverse(leftSum, rightSum + delta * multiplier, index1 - 1, index2);
    }
    if (index2 >= R) {
      long delta = binomial[index2][R] - binomial[index2 - 1][R];
      long multiplier = binomial[index1][R];
      traverse(leftSum + delta * multiplier, rightSum, index1, index2 - 1);
    }
  }

  long explore(long leftSum, long rightSum, int index1, int index2) {
    long diff = Math.abs(leftSum - rightSum);
    if (diff - binomial[index1][R] * binomial[index2][R] > minDifference) return 0L;
    String state = leftSum + ":" + index1 + ":" + index2;
    Long saved = cache.get(state);
    if (saved != null) return saved;
    if (index1 < R || index2 < R) {
      if (index1 >= numA[index1 + index2] && index2 >= numB[index1 + index2]) {
        int combined = index1 + index2;
        index1 -= numA[combined];
        index2 -= numB[combined];
        return binomial[index1 + index2][index1];
      }
      return 0L;
    }
    long result = 0L;
    char token = chars.charAt(index1 + index2 - 1);
    if (token != 'B') {
      long delta = binomial[index1][R] - binomial[index1 - 1][R];
      long multiplier = binomial[index2][R];
      result += explore(leftSum, rightSum + delta * multiplier, index1 - 1, index2);
    }
    if (token != 'A') {
      long delta = binomial[index2][R] - binomial[index2 - 1][R];
      long multiplier = binomial[index1][R];
      result += explore(leftSum + delta * multiplier, rightSum, index1, index2 - 1);
    }
    cache.put(state, result);
    return result;
  }

  void run() {
    R = nextIntValue();
    C = nextIntValue();
    for (int i = 0; i <= 2 * (R + C); i++) {
      for (int j = 0; j <= i; j++) {
        if (j == 0 || j == i) binomial[i][j] = 1;
        else binomial[i][j] = binomial[i - 1][j - 1] + binomial[i - 1][j];
      }
    }
    long left = 0, right = 0;
    int idx1 = R + C, idx2 = R + C;
    while (idx1 >= R && idx2 >= R) {
      if (left > right) {
        long delta = binomial[idx1][R] - binomial[idx1 - 1][R];
        long multiplier = binomial[idx2][R];
        right += delta * multiplier;
        idx1--;
      } else {
        long delta = binomial[idx2][R] - binomial[idx2 - 1][R];
        long multiplier = binomial[idx1][R];
        left += delta * multiplier;
        idx2--;
      }
    }
    minDifference = Math.abs(left - right);
    traverse(0, 0, R + C, R + C);
    chars = nextStringValue();
    for (int i = 0; i < 2 * (R + C); i++) {
      numA[i + 1] = numA[i] + (chars.charAt(i) == 'A' ? 1 : 0);
      numB[i + 1] = numB[i] + (chars.charAt(i) == 'B' ? 1 : 0);
    }
    long total = explore(0, 0, R + C, R + C);
    pw.println(total);
  }
}
